import openpyxl

wb = openpyxl.load_workbook('/workspace/task/output.xlsx')

src = wb['Source']
src2 = wb['Source2']
res = wb['Result']

# distinct values in Source, in order of appearance
src_vals = []
for row in src.iter_rows(min_row=2, values_only=True):
    v = row[1]
    if v is not None and v not in src_vals:
        src_vals.append(v)

# distinct values in Source2
src2_vals = []
for row in src2.iter_rows(min_row=2, values_only=True):
    v = row[0]
    if v is not None and v not in src2_vals:
        src2_vals.append(v)

result = []
for v in src_vals:
    if v == 2:
        if v in src2_vals:
            result.append(v)
    else:
        if v not in src2_vals:
            result.append(v)

print("source distinct:", src_vals)
print("source2 distinct:", src2_vals)
print("result:", result)

# write into Result A2:A8
for i, v in enumerate(result):
    res.cell(row=2 + i, column=1, value=v)

wb.save('/workspace/task/output.xlsx')
print("saved")
